const i = $input.first().json;

// `keywords` and `concepts` may arrive as real arrays or as JSON strings, depending
// on how the caller mapped them through the Execute Workflow node. Both are accepted.
const parse = v => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim().startsWith('[')) {
    try { return JSON.parse(v); } catch (e) { return []; }
  }
  return [];
};
const clean = v => parse(v).map(s => String(s ?? '').trim()).filter(Boolean);

const style = String(i.style ?? '').trim() || 'beer';

// ⛔ Sensory descriptors must not reach the retriever. `bitter` matches 520 chunks and
// `sweet` 301 (measured 2026-09-17), so searching them returns whatever sits nearest
// the bare word. Document frequency cannot separate them automatically -- `thick` (47)
// and `vanilla` (37) overlap -- so the caller names them here and they are dropped.
const excl = new Set(clean(i.exclude).map(s => s.toLowerCase()));

const dedupe = list => {
  const out = [], seen = new Set();
  for (const t of list) {
    const k = t.toLowerCase();
    if (excl.has(k) || seen.has(k)) continue;
    seen.add(k);
    out.push(t);
  }
  return out;
};

// Collapse a longer term onto a shorter one it contains: "crushed poppy seeds" and
// "poppy seeds" are the same search, and the shorter retrieves better in both arms.
//
// ⛔ WITHIN a class only. Across classes the same rule would drop the concept
// "black forest cake" in favour of the ingredient "cake", which is the opposite of
// useful. Case is preserved on whatever survives -- corpus_vocabulary_gap's phrase
// arm keys on a leading capital, so lowercasing would hide product names from the
// gap detector inside wf-step-retrieve.
const collapse = list => list.filter(t =>
  !list.some(o => o.length < t.length && t.toLowerCase().includes(o.toLowerCase())));

const concept_terms = collapse(dedupe(clean(i.concepts)));

// ⛔ A term appearing in BOTH lists counts as a concept. It only reaches `concepts`
// because the parse step made a deliberate positive call, and the reverse error is
// the bug this split exists to fix -- asking the web how much Mákos Guba to add.
const isConcept = new Set(concept_terms.map(s => s.toLowerCase()));
let usage_terms = collapse(dedupe(clean(i.keywords)))
  .filter(t => !isConcept.has(t.toLowerCase()));

if (!usage_terms.length && !concept_terms.length) usage_terms = [style];

const k = Number(i.top_k);
const mode = String(i.mode ?? 'text').trim().toLowerCase() === 'rows' ? 'rows' : 'text';

return [{ json: {
  // One flat union so Probe corpus stays a SINGLE call covering both classes.
  terms: [...usage_terms, ...concept_terms],
  usage_terms,
  concept_terms,
  style,
  mode,
  session_id: String(i.session_id ?? '').trim(),
  top_k: Number.isFinite(k) && k > 0 ? Math.min(Math.round(k), 8) : 8,
}}];

const src = $('Normalise input').first().json;

// Probe rows come back unordered (the function does SELECT DISTINCT), so re-key them
// against the normalised lists -- that is what keeps the caller's order in the queries
// and in the [S..] numbering.
const hits = new Map();
for (const it of $input.all()) {
  if (it.json.term == null) continue;
  hits.set(String(it.json.term), Number(it.json.fts_hits) || 0);
}
const covers = t => (hits.get(t) ?? 0) > 5;

return [{ json: {
  ...src,
  covered:            src.usage_terms.filter(covers),
  uncovered:          src.usage_terms.filter(t => !covers(t)),
  covered_concepts:   src.concept_terms.filter(covers),
  uncovered_concepts: src.concept_terms.filter(t => !covers(t)),
}}];

const s = $('Split coverage').first().json;

// ⛔ Separate budgets, not one shared slice. A brief with four novel ingredients
// would otherwise eat the whole cap and the concept lookup never runs -- and the
// concept is usually the thing the brewer actually cares about.
// Each call is a live SearXNG round trip: measured 8.7-14.9 s on 2026-09-17.
const usage = s.uncovered.slice(0, 3).map(term => ({ json: {
  term, kind: 'usage',
  web_query: `${term} homebrewing how to use it, how much and when to add`,
}}));

// ⛔ No style here, and no "homebrew". measured 2026-09-17: with the style attached,
// "Mákos Guba pastry stout homebrew how much to use and when to add" returned three
// generic pastry-stout pages and a steak-and-ale pie. Without it,
// "what is Mákos Guba Hungarian dessert ingredients and flavour" returned the dish
// itself -- "hearty, but not overly rich… not overly sweet" -- which is the brief.
const concept = s.uncovered_concepts.slice(0, 2).map(term => ({ json: {
  term, kind: 'concept',
  web_query: `what is ${term} — ingredients, flavour and description`,
}}));

return [...usage, ...concept];

const src  = $('Split coverage').first().json;
const mode = String(src.mode ?? 'text').toLowerCase() === 'rows' ? 'rows' : 'text';

// ⛔ .all(), not .first(). Library search runs in mode:"each" over the items Plan
// searches emits -- up to two, one per group -- so .first() reads only the usage
// group and silently drops every concept passage. Index-aligned with Plan searches,
// the same pairing Merge passages relies on in wf-step-retrieve-multi.
const planned = $('Plan searches').all().map(i => i.json);
const libr    = $('Library search').all().map(i => i.json ?? {});
const rowsOf = group => {
  const idx = planned.findIndex(p => p.group === group);
  if (idx < 0) return [];
  // Always Output Data is ON inside wf-step-retrieve, so a zero-row search arrives
  // as an empty array; filtering on chunk_id turns that back into "no results".
  return (libr[idx]?.rows ?? []).filter(r => r && r.chunk_id != null);
};
// Both groups are [S..]: the marker encodes PROVENANCE, not topic, and a covered
// concept is a vetted library passage like any other. Deduped -- a passage can win
// both searches.
const seenChunk = new Set();
const rows = [...rowsOf('usage'), ...rowsOf('concept')]
  .filter(r => !seenChunk.has(r.chunk_id) && seenChunk.add(r.chunk_id));

// ⛔ `kind` CANNOT be read off Web gaps. measured on execution 2084: the HTTP node
// returns only the webarm response -- {query, rows, skipped, dropped, secs} -- and
// nothing from the request item. Pair on the echoed `query`, which is the verbatim
// web_query Fan uncovered sent.
const kindOf = new Map($('Fan uncovered').all().map(i => [i.json.web_query, i.json.kind]));

// ⛔ `Web gaps` only runs on the true arm, so referencing it on the false arm THROWS
// rather than returning empty. try/catch is load-bearing -- the same reason it is in
// wf-step-retrieve's Return rows. onError:continueRegularOutput also means a failed
// call arrives carrying `error` and no `rows`; that is treated as no web results.
const web = [], concepts = [];
const seenUrl = new Set();   // shared: one passage per source across BOTH arms
try {
  for (const it of $('Web gaps').all()) {
    const res = it.json ?? {};
    const bucket = kindOf.get(res.query) === 'concept' ? concepts : web;
    for (const r of (res.rows ?? [])) {
      if (!r || seenUrl.has(r.url)) continue;
      seenUrl.add(r.url);
      bucket.push(r);
    }
  }
} catch (e) { /* gate was false: no web arm on this path */ }

const gap        = src.uncovered ?? [];
const gapConcept = src.uncovered_concepts ?? [];
const asked = planned.map(p => `"${p.query}"`).join(', ');
const q = t => `"${t}"`;

// Structured shape -- for capabilities. Empty is a valid answer, not an error.
if (mode === 'rows') {
  return [{ json: {
    query: planned.map(p => p.query).join(' | '),
    count: rows.length,
    covered: src.covered, covered_concepts: src.covered_concepts,
    gap, gap_concepts: gapConcept,
    web, concepts, rows,
  }}];
}

// Text shape -- for the model. ONE item, ONE key.
if (!rows.length && !web.length && !concepts.length) {
  return [{ json: { response: `No passages in the library matched ${asked}.` } }];
}

const blocks = [rows.length
  ? `${rows.length} passages from the library, searched as ${asked}:\n\n` +
    rows.map((x, n) =>
      `[S${n + 1}] ${x.doc_title} · ${x.heading}${x.page ? ` · p.${x.page}` : ''}\n${x.text}`
    ).join('\n\n')
  : `No passages in the library matched ${asked}.`];

// ⛔ [W..] is a DIFFERENT marker from [S..] on purpose, and the sentence below is an
// instruction the model reads, not decoration. Web passages carry none of the
// library's editorial vetting and must never be presented as though they do.
if (web.length) {
  blocks.push(`---\n` +
    (gap.length
      ? `Your library has never seen ${gap.map(q).join(', ')}, so these came from the web.\n`
      : `These came from the web, not your library.\n`) +
    `Cite them as [W1], [W2] — NOT as [S1] — and tell the reader plainly that this ` +
    `part is from the web and is not in their library.\n\n` +
    web.map((x, n) => `[W${n + 1}] ${x.url}${x.heading ? ` · ${x.heading}` : ''}\n${x.text}`).join('\n\n'));
} else if (gap.length) {
  blocks.push(`The library does not cover ${gap.map(q).join(', ')}, and no usable web source was reachable.`);
}

// ⛔ A THIRD marker, not more [W..]. A concept passage is a food blog describing a
// dessert: authoritative about the dessert, zero brewing authority. Dropped into the
// [W..] block the model reads a bread-pudding recipe as brewing guidance.
if (concepts.length) {
  const label = concepts.length === 1 ? '[C1] describes' : `[C1]..[C${concepts.length}] describe`;
  blocks.push(`---\n` +
    `${label} ${gapConcept.map(q).join(', ')} — what the brewer asked the beer to taste ` +
    `LIKE. They are NOT brewing sources: do not take quantities, methods or timings ` +
    `from them. Use them only to decide which flavours the recipe has to hit.\n\n` +
    concepts.map((x, n) => `[C${n + 1}] ${x.url}${x.heading ? ` · ${x.heading}` : ''}\n${x.text}`).join('\n\n'));
} else if (gapConcept.length) {
  blocks.push(`No usable description of ${gapConcept.map(q).join(', ')} was reachable on the web.`);
}

return [{ json: { response: blocks.join('\n\n') } }];

const s = $('Split coverage').first().json;
const groups = [];
if (s.covered.length)          groups.push({ group: 'usage',   query: s.covered.join(' ') });
if (s.covered_concepts.length) groups.push({ group: 'concept', query: s.covered_concepts.join(' ') });

// ⛔ wf-step-retrieve THROWS on an empty query. With nothing covered on either
// side the style is all that is left, and Normalise input guarantees it is set.
if (!groups.length) groups.push({ group: 'usage', query: s.style });

return groups.map(g => ({ json: { ...g, top_k: s.top_k, mode: 'rows', session_id: s.session_id } }));
